-- Why: TPRM had exactly one questionnaire, hardcoded in the
-- VendorQuestionnaire page (Sentinel VSQ v1.0). A third-party risk programme
-- needs a library of assessment instruments matched to the vendor lifecycle
-- (intake, cloud security, privacy, AI, sub-processors, renewal, exit).
--
-- This migration adds `vendor_assessment_templates` (org-scoped, RLS) and
-- seeds the 10 built-in questionnaire packs, grouped under the platform's
-- TPRM module taxonomy. The VSQ pack ports the shipped v1.0 questions
-- unchanged so historical responses stay comparable. The CAIQ packs are
-- domain-level screens aligned to the 16 CSA CCM/CAIQ v4 domains — a
-- structured screen, NOT the verbatim licensed 200+-question CSA instrument
-- (the description says so; the full CAIQ submission is requested as
-- evidence). Responses continue to snapshot template name, version and
-- questions at submit time, so editing a template never rescores history.
-- Idempotent: table IF NOT EXISTS; seeds keyed on (org_id, slug).

create table if not exists public.vendor_assessment_templates (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null default current_user_org_id(),
  slug        text not null,
  name        text not null,
  module      text not null,
  version     text not null,
  description text,
  questions   jsonb not null default '[]',
  is_builtin  boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint vendor_assessment_templates_slug_unique unique (org_id, slug)
);
comment on table public.vendor_assessment_templates is
  'TPRM questionnaire packs. questions is [{id,text,category,options:[{value,label,points}]}]. Responses snapshot the template at submit time.';

alter table public.vendor_assessment_templates enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename='vendor_assessment_templates' and policyname='vendor_assessment_templates_org_isolation') then
    create policy vendor_assessment_templates_org_isolation on public.vendor_assessment_templates
      for all using (org_id = current_user_org_id())
      with check (org_id = current_user_org_id());
  end if;
end $$;


insert into public.vendor_assessment_templates (org_id, slug, name, module, version, description, questions, is_builtin)
select '00000000-0000-0000-0000-000000000001'::uuid, 'vsq-core', 'Vendor Security Questionnaire – Core', 'Vendor Intake & Inherent Risk Assessment', 'v1.0', 'The platform''s core security screen for new vendors — ported unchanged from Sentinel VSQ v1.0 so historical responses stay comparable.', '[{"id": "Q1", "text": "Data encryption at rest", "category": "Data Security", "options": [{"value": "yes", "label": "Yes — AES-256 or equivalent", "points": 10}, {"value": "partial", "label": "Partial — some systems encrypted", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q2", "text": "SOC 2 Type II certification", "category": "Certification", "options": [{"value": "yes", "label": "Yes — current certificate", "points": 10}, {"value": "in_progress", "label": "In progress", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q3", "text": "GDPR data processing agreement signed", "category": "Compliance", "options": [{"value": "yes", "label": "Yes — signed and current", "points": 10}, {"value": "pending", "label": "Pending signature", "points": 3}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q4", "text": "Documented incident response plan", "category": "Incident Response", "options": [{"value": "yes", "label": "Yes — tested in the last 12 months", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q5", "text": "Annual penetration testing", "category": "Security Testing", "options": [{"value": "yes", "label": "Yes — third-party pentest", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q6", "text": "Data residency controls for EU/US data", "category": "Data Governance", "options": [{"value": "yes", "label": "Yes — full geographic controls", "points": 10}, {"value": "partial", "label": "Partial — limited controls", "points": 4}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q7", "text": "AI model access logging and audit trails", "category": "AI Governance", "options": [{"value": "yes", "label": "Yes — full audit logging", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q8", "text": "Employee security awareness training", "category": "People Security", "options": [{"value": "quarterly", "label": "Quarterly or more frequent", "points": 10}, {"value": "yes", "label": "Annual training", "points": 6}, {"value": "no", "label": "No formal training", "points": 0}]}, {"id": "Q9", "text": "Business continuity and disaster recovery plan", "category": "Resilience", "options": [{"value": "yes", "label": "Yes — tested BCP/DRP in place", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "Q10", "text": "Sub-processor disclosures provided", "category": "Third-Party Risk", "options": [{"value": "yes", "label": "Yes — full list disclosed", "points": 10}, {"value": "partial", "label": "Partial — key sub-processors only", "points": 4}, {"value": "no", "label": "No disclosure", "points": 0}]}]'::jsonb, true
 where not exists (select 1 from public.vendor_assessment_templates
                    where org_id = '00000000-0000-0000-0000-000000000001'::uuid and slug = 'vsq-core');

