select '00000000-0000-0000-0000-000000000001'::uuid, 'caiq-v4', 'CAIQ v4.1 Assessment', 'CAIQ Cloud Security Assessment', 'v4.1-aligned', 'Domain-level screen aligned to the 16 CSA CCM/CAIQ v4 domains. One question per domain — a structured screen, not the verbatim 200+-question CSA instrument; request the vendor''s full CAIQ submission as evidence.', '[{"id": "AA", "text": "Independent audits and assurance reports are performed on a defined cadence and shared with customers", "category": "Audit & Assurance", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "AIS", "text": "Applications and APIs are developed under a secure SDLC with security testing before release", "category": "Application & Interface Security", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "BCR", "text": "Business continuity plans exist, are exercised, and cover the services we consume", "category": "Business Continuity & Operational Resilience", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "CCC", "text": "Production changes follow a documented change-management process with rollback", "category": "Change Control & Configuration", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "CEK", "text": "Encryption is applied in transit and at rest with documented key-management (rotation, custody)", "category": "Cryptography, Encryption & Key Management", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "DCS", "text": "Physical and environmental controls protect facilities hosting our data", "category": "Datacenter Security", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "DSP", "text": "Data is classified, handled and disposed of according to a documented lifecycle policy", "category": "Data Security & Privacy Lifecycle", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "GRC", "text": "A risk-management programme with defined ownership and periodic review is in place", "category": "Governance, Risk & Compliance", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "HRS", "text": "Personnel screening, onboarding/offboarding and confidentiality obligations are enforced", "category": "Human Resources Security", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "IAM", "text": "Access follows least privilege with MFA and periodic access reviews", "category": "Identity & Access Management", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "IVS", "text": "Network segmentation, hardening baselines and vulnerability management cover the infrastructure", "category": "Infrastructure & Virtualization Security", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "LOG", "text": "Security-relevant events are logged, retained and monitored with alerting", "category": "Logging & Monitoring", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "SEF", "text": "Incident response includes customer notification commitments and forensic capability", "category": "Security Incident Management & Forensics", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "STA", "text": "Third-party/supply-chain risk is assessed and flowed down contractually", "category": "Supply Chain, Transparency & Accountability", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "TVM", "text": "Vulnerabilities are identified, prioritised and remediated within defined SLAs", "category": "Threat & Vulnerability Management", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "UEM", "text": "Endpoints accessing service infrastructure are managed, encrypted and patched", "category": "Universal Endpoint Management", "options": [{"value": "yes", "label": "Yes — implemented and evidenced", "points": 10}, {"value": "partial", "label": "Partially implemented", "points": 5}, {"value": "no", "label": "No", "points": 0}]}]'::jsonb, true
 where not exists (select 1 from public.vendor_assessment_templates
                    where org_id = '00000000-0000-0000-0000-000000000001'::uuid and slug = 'caiq-v4');

