select '00000000-0000-0000-0000-000000000001'::uuid, 'ai-llm', 'AI/LLM Vendor Assessment', 'AI Vendor Assessment', 'v1.0', 'Due diligence for vendors whose service embeds AI/LLM capability: training-data use, oversight, transparency and EU AI Act posture.', '[{"id": "A1", "text": "Customer data excluded from model training by default", "category": "Data Use", "options": [{"value": "yes", "label": "Yes — contractual default exclusion", "points": 10}, {"value": "optout", "label": "Opt-out available", "points": 5}, {"value": "no", "label": "Used for training, no opt-out", "points": 0}]}, {"id": "A2", "text": "Model provenance disclosed (base models, versions, hosting)", "category": "Transparency", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A3", "text": "Documented evaluation and red-teaming before release", "category": "Safety", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A4", "text": "Guardrails against harmful or off-policy output", "category": "Safety", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A5", "text": "Accuracy limitations and hallucination risks disclosed to users", "category": "Transparency", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A6", "text": "PII in prompts: minimisation, redaction or blocking controls", "category": "Privacy", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A7", "text": "Prompt/response logging with retention disclosed and configurable", "category": "Logging", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A8", "text": "Third-party model APIs used are disclosed as sub-processors", "category": "Supply Chain", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A9", "text": "EU AI Act role (provider/deployer/importer) assessed and stated", "category": "Regulatory", "options": [{"value": "yes", "label": "Yes — role and obligations documented", "points": 10}, {"value": "partial", "label": "Assessment in progress", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A10", "text": "Human oversight supported for consequential decisions", "category": "Oversight", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A11", "text": "AI incident reporting channel and commitment to notify customers", "category": "Incidents", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "A12", "text": "Model changes with material behaviour impact are announced in advance", "category": "Change Management", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}]'::jsonb, true
 where not exists (select 1 from public.vendor_assessment_templates
                    where org_id = '00000000-0000-0000-0000-000000000001'::uuid and slug = 'ai-llm');

