category": "Concentration", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "S8", "text": "Sub-processor data deleted on exit, with certification available", "category": "Exit", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}]'::jsonb, true
