select '00000000-0000-0000-0000-000000000001'::uuid, 'renewal', 'Vendor Renewal / Reassessment', 'Vendor Approval & Renewal Workflow', 'v1.0', 'Annual renewal gate: what changed since the last assessment and whether the relationship still fits its tier.', '[{"id": "R1", "text": "Material changes to service scope, architecture or ownership since last review", "category": "Change", "options": [{"value": "none", "label": "No material change", "points": 10}, {"value": "minor", "label": "Minor changes, reviewed", "points": 6}, {"value": "major", "label": "Major changes, unreviewed", "points": 0}]}, {"id": "R2", "text": "Security or privacy incidents affecting us since last review", "category": "Incidents", "options": [{"value": "none", "label": "None", "points": 10}, {"value": "handled", "label": "Incident(s) — handled and disclosed", "points": 5}, {"value": "undisclosed", "label": "Incident(s) — poorly handled or undisclosed", "points": 0}]}, {"id": "R3", "text": "SLA performance met over the review period", "category": "Performance", "options": [{"value": "yes", "label": "Met or exceeded", "points": 10}, {"value": "partial", "label": "Occasional misses", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "R4", "text": "Certifications (SOC 2/ISO/other) renewed and current", "category": "Assurance", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "R5", "text": "Open findings from previous assessments remediated", "category": "Findings", "options": [{"value": "closed", "label": "All closed", "points": 10}, {"value": "progress", "label": "On-track remediation", "points": 6}, {"value": "stalled", "label": "Stalled or ignored", "points": 0}]}, {"id": "R6", "text": "Contract terms (DPA, liability, exit) still adequate", "category": "Contract", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "R7", "text": "Vendor tier and criticality rating still correct", "category": "Tiering", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "R8", "text": "Spend and usage consistent with the approved business case", "category": "Value", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}]'::jsonb, true
 where not exists (select 1 from public.vendor_assessment_templates
