select '00000000-0000-0000-0000-000000000001'::uuid, 'offboarding', 'Vendor Offboarding Checklist', 'Vendor Exit / Offboarding Assessment', 'v1.0', 'Exit verification: nothing of ours remains with the vendor, and nothing of theirs remains in us.', '[{"id": "X1", "text": "Our data returned or destroyed, with written certification", "category": "Data", "options": [{"value": "certified", "label": "Destroyed/returned with certificate", "points": 10}, {"value": "confirmed", "label": "Confirmed verbally/by email", "points": 5}, {"value": "no", "label": "Not confirmed", "points": 0}]}, {"id": "X2", "text": "Vendor access to our systems and networks revoked", "category": "Access", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X3", "text": "Shared credentials, API keys and certificates rotated", "category": "Credentials", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X4", "text": "Integrations, webhooks and data feeds disabled", "category": "Integrations", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X5", "text": "Surviving contractual obligations (confidentiality, audit rights) recorded", "category": "Contract", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X6", "text": "Sub-processors instructed to delete our data", "category": "Fourth Party", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "partial", "label": "Partial", "points": 5}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X7", "text": "Final commercial settlement completed", "category": "Commercial", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}, {"id": "X8", "text": "Exit lessons and replacement mapping recorded", "category": "Closure", "options": [{"value": "yes", "label": "Yes", "points": 10}, {"value": "no", "label": "No", "points": 0}]}]'::jsonb, true
 where not exists (select 1 from public.vendor_assessment_templates
                    where org_id = '00000000-0000-0000-0000-000000000001'::uuid and slug = 'offboarding');
